describe('Edit Task Feature', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="task-list"]').should('be.visible');
  });

  it('should edit an existing task successfully', () => {
    const originalTaskName = 'Complete project report';
    const updatedTaskName = 'Complete project report - Updated';

    cy.get('[data-testid="task-item"]').first().within(() => {
      cy.get('[data-testid="task-name"]').should('contain', originalTaskName);
      cy.get('[data-testid="edit-button"]').click();
    });

    cy.get('[data-testid="edit-modal"]').should('be.visible');
    cy.get('[data-testid="task-input"]').clear().type(updatedTaskName);
    cy.get('[data-testid="save-button"]').click();

    cy.get('[data-testid="edit-modal"]').should('not.exist');
    cy.get('[data-testid="task-item"]').first().within(() => {
      cy.get('[data-testid="task-name"]').should('contain', updatedTaskName);
    });
  });

  it('should cancel editing without saving changes', () => {
    const originalTaskName = 'Complete project report';
    const attemptedTaskName = 'This should not be saved';

    cy.get('[data-testid="task-item"]').first().within(() => {
      cy.get('[data-testid="task-name"]').should('contain', originalTaskName);
      cy.get('[data-testid="edit-button"]').click();
    });

    cy.get('[data-testid="edit-modal"]').should('be.visible');
    cy.get('[data-testid="task-input"]').clear().type(attemptedTaskName);
    cy.get('[data-testid="cancel-button"]').click();

    cy.get('[data-testid="edit-modal"]').should('not.exist');
    cy.get('[data-testid="task-item"]').first().within(() => {
      cy.get('[data-testid="task-name"]').should('contain', originalTaskName);
    });
  });

  it('should not save task with empty name', () => {
    cy.get('[data-testid="task-item"]').first().within(() => {
      cy.get('[data-testid="edit-button"]').click();
    });

    cy.get('[data-testid="edit-modal"]').should('be.visible');
    cy.get('[data-testid="task-input"]').clear();
    cy.get('[data-testid="save-button"]').should('be.disabled');
  });

  it('should edit task with special characters', () => {
    const specialCharacterTask = 'Task with @#$% & special chars!';

    cy.get('[data-testid="task-item"]').first().within(() => {
      cy.get('[data-testid="edit-button"]').click();
    });

    cy.get('[data-testid="edit-modal"]').should('be.visible');
    cy.get('[data-testid="task-input"]').clear().type(specialCharacterTask);
    cy.get('[data-testid="save-button"]').click();

    cy.get('[data-testid="task-item"]').first().within(() => {
      cy.get('[data-testid="task-name"]').should('contain', specialCharacterTask);
    });
  });
});
